{
  "decision-packing-upgrades-under-depreciation-ceiling": "WITH quotes AS (SELECT quote_id, packs_hour, purchase_cents, (purchase_cents - residual_cents) / life_years AS depreciation FROM upgrade_quote), selections AS (SELECT quote_id AS quote_ids, packs_hour AS added_packs_hour, purchase_cents AS spend_cents, depreciation AS annual_dep_cents FROM quotes UNION ALL SELECT a.quote_id || ',' || b.quote_id, a.packs_hour + b.packs_hour, a.purchase_cents + b.purchase_cents, a.depreciation + b.depreciation FROM quotes AS a JOIN quotes AS b ON a.quote_id COLLATE BINARY < b.quote_id) SELECT quote_ids, added_packs_hour, spend_cents, annual_dep_cents FROM selections WHERE spend_cents <= 12000 AND annual_dep_cents <= 3000 ORDER BY added_packs_hour DESC, spend_cents ASC, quote_ids COLLATE BINARY ASC LIMIT 1",
  "decision-pair-relief-shifts-to-cover-two-surges": "SELECT a.offer_code AS first_offer, b.offer_code AS second_offer, MIN(p.early_need, a.early_slots + b.early_slots) + MIN(p.late_need, a.late_slots + b.late_slots) AS covered_calls, a.fee_cents + b.fee_cents AS total_cents FROM relief_offers AS a JOIN relief_offers AS b ON a.offer_code COLLATE BINARY < b.offer_code CROSS JOIN surge_plan AS p WHERE a.fee_cents + b.fee_cents <= p.cap_cents ORDER BY covered_calls DESC, total_cents ASC, first_offer COLLATE BINARY ASC, second_offer COLLATE BINARY ASC LIMIT 1",
  "decision-pair-repairs-within-shutdown-window": "SELECT a.card_id AS first_card, b.card_id AS second_card, a.monthly_liters + b.monthly_liters AS saved_liters, w.setup_min + a.work_min + b.work_min AS shutdown_minutes, w.window_id AS window_id FROM repair_cards AS a JOIN repair_cards AS b ON a.loop_code = b.loop_code AND a.card_id COLLATE BINARY < b.card_id JOIN loop_windows AS w ON w.loop_code = a.loop_code WHERE w.setup_min + a.work_min + b.work_min <= w.window_min ORDER BY saved_liters DESC, shutdown_minutes ASC, first_card COLLATE BINARY ASC, second_card COLLATE BINARY ASC LIMIT 1",
  "decision-paired-glaze-weighted-median": "WITH batches AS (SELECT ((CASE WHEN first_below = 1 THEN first_mg_l / 2.0 ELSE first_mg_l END) + (CASE WHEN second_below = 1 THEN second_mg_l / 2.0 ELSE second_mg_l END)) / 2.0 AS concentration, jars FROM glaze_pairs WHERE first_mg_l IS NOT NULL AND second_mg_l IS NOT NULL), weights AS (SELECT concentration, SUM(jars) AS weight FROM batches GROUP BY concentration), ranked AS (SELECT concentration, SUM(weight) OVER (ORDER BY concentration) AS cumulative_weight, SUM(weight) OVER () AS total_weight FROM weights) SELECT concentration AS median_mg_l FROM ranked WHERE cumulative_weight >= total_weight - cumulative_weight ORDER BY concentration ASC LIMIT 1"
}
